// Remove tudo que não é mensagem de cliente: eco, grupo, reação,
// status e protocolo. Sem isso o agente responde a si mesmo.
const body = $input.first().json.body;
if (!body) return [];

const msg = body.data || body;
const key = msg.key || {};
const message = msg.message || {};

if (key.fromMe === true) return [];
if (key.remoteJid && key.remoteJid.includes('@g.us')) return [];
if (key.remoteJid === 'status@broadcast') return [];
if (message.reactionMessage) return [];
if (message.editedMessage || message.protocolMessage) return [];
if (msg.messageType === 'protocolMessage') return [];

const telefone = (key.remoteJid || '').replace('@s.whatsapp.net', '');
if (!telefone) return [];

// ---------- Números sem IA ----------
// Quem está nesta lista recebe apenas os avisos automáticos do site: a
// Júlia não responde. A Maurizia é a faxineira, não é cliente — se a IA
// respondesse aqui, ela levaria orçamento de aluguel como resposta a um
// "ok, combinado".
//
// O grupo dos donos não precisa entrar: mensagem de grupo já sai fora
// acima, na checagem de '@g.us'.
// COMPARAR A STRING CRUA NÃO FUNCIONA. O JID brasileiro chega em dois
// formatos, conforme o número foi registrado no WhatsApp: com o nono
// dígito ('5531975278287') e sem ele ('553175278287'). A Maurizia chega
// SEM, e por isso em 13/08/2026 a Júlia respondeu o "obrigada" dela e
// ainda ofereceu data. A chave normaliza para DDI + DDD + os 8 últimos
// dígitos, que são iguais nos dois formatos.
function chaveTelefone(numero) {
  const d = String(numero || '').replace(/\D/g, '');
  return d.length >= 12 ? d.slice(0, 4) + d.slice(-8) : d;
}

const SEM_IA = [
  '5531975278287', // Maurizia — faxineira
  '5531992025806', // Renato — piscineiro
].map(chaveTelefone);

if (SEM_IA.includes(chaveTelefone(telefone))) return [];

let texto = '';
let tipo = 'texto';
if (message.conversation) {
  texto = message.conversation;
} else if (message.extendedTextMessage) {
  texto = message.extendedTextMessage.text || '';
} else if (message.audioMessage) {
  tipo = 'audio';
} else if (message.imageMessage) {
  tipo = 'imagem';
  texto = message.imageMessage.caption || '';
} else {
  return [];
}

return [{
  json: {
    telefone,
    texto: (texto || '').trim(),
    tipo,
    nomeWhats: msg.pushName || '',
    messageId: key.id || '',
    recebidoEm: new Date().toISOString(),
  }
}];

// O porteiro da rajada: de todas as execucoes disparadas por uma sequencia
// de mensagens, so UMA responde — a que trouxe a mensagem mais nova.
//
// Em 14/08/2026 um cliente mandou cinco mensagens em quinze segundos e
// levou cinco respostas, cada uma escrita sem saber das outras. Agora cada
// mensagem e enfileirada, todas esperam, e quem acorda vendo que ja chegou
// coisa mais nova desiste em silencio. A ultima responde por todas.
const eu = $('Filtrar Mensagem').first().json;

const pendentes = $input.all()
  .map((i) => i.json)
  .filter((m) => m && m.id);

// Fila vazia: outra execucao ja levou este lote junto com o dela.
if (pendentes.length === 0) return [];

pendentes.sort((a, b) => {
  const t = String(a.recebido_em).localeCompare(String(b.recebido_em));
  // Empate no mesmo milissegundo: o id desempata. Sem criterio estavel,
  // duas execucoes podiam ordenar a fila diferente uma da outra, cada uma
  // eleger um "ultimo" e as duas responderem — ou nenhuma.
  return t !== 0 ? t : String(a.id).localeCompare(String(b.id));
});

// Sobra de execucao morta (n8n reiniciado no meio da espera) fica na fila
// para sempre. Nao pode voltar a ser respondida semanas depois, no meio de
// outra conversa — mas sai marcada junto, senao entope a fila do numero.
const CORTE_MS = 10 * 60 * 1000;
const agora = Date.now();
const recentes = pendentes.filter(
  (m) => agora - new Date(m.recebido_em).getTime() <= CORTE_MS);

if (recentes.length === 0) return [];

const ultima = recentes[recentes.length - 1];

// Nao sou o mais novo: existe uma execucao ainda esperando que vai
// responder por mim tambem. Sair daqui e o certo.
if (ultima.message_id !== eu.messageId) return [];

const temTexto = recentes.some((m) => (m.texto || '').trim());

const texto = recentes
  .map((m) => (m.texto || '').trim() || (m.tipo === 'audio' ? '[audio recebido]' : ''))
  .filter(Boolean)
  .join('\n');

return [{
  json: {
    telefone: eu.telefone,
    texto,
    // So vira "audio" quando NAO veio texto nenhum: audio junto de texto
    // nao pode transformar a resposta num pedido para escrever.
    tipo: temTexto ? 'texto' : 'audio',
    nomeWhats: eu.nomeWhats,
    quantidade: recentes.length,
    // Marca a fila inteira, inclusive as sobras velhas: elas nao foram
    // respondidas, mas tambem nao podem ficar rondando.
    idsFiltro: 'in.(' + pendentes.map((m) => m.id).join(',') + ')',
  }
}];

// Funde o que a IA extraiu com o que a sessao ja guardava. Dado novo
// vence dado velho; o que nao veio, mantem.
const base = $('Montar Extração').first().json;
const sessao = base.sessao || {};

let extraido = {};
try {
  const bruto = $input.first().json.choices[0].message.content;
  extraido = JSON.parse(bruto);
} catch (e) {
  extraido = { intencao: 'OUTRO' };
}

const escolher = (novo, antigo) =>
  (novo !== null && novo !== undefined && novo !== '') ? novo : (antigo ?? null);

// ---------- O ano, quando a pessoa nao disse nenhum ----------
// Isso NAO pode ficar por conta do modelo. Pedimos "sexta dia 2 ate domingo
// dia 04/10" numa segunda de agosto de 2026 e ele respondeu 2027 duas vezes
// seguidas, com o prompt mandando o contrario. Quem nao diz o ano quer a
// PROXIMA vez que aquele dia e mes acontecem — e isso e conta, nao palpite.
const hoje = base.hojeISO || new Date().toISOString().slice(0, 10);

function proximaOcorrencia(iso) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(iso || '')) return iso;
  const anoHoje = Number(hoje.slice(0, 4));
  const mesDia = iso.slice(5);
  const desteAno = anoHoje + '-' + mesDia;
  return desteAno >= hoje ? desteAno : (anoHoje + 1) + '-' + mesDia;
}

let exCheckin = extraido.data_checkin;
let exCheckout = extraido.data_checkout;

if (exCheckin && extraido.ano_dito !== true) {
  const corrigido = proximaOcorrencia(exCheckin);
  // A saida anda junto com a entrada: o que a pessoa disse foi a duracao,
  // e mexer so na entrada inverteria o periodo.
  if (exCheckout && /^\d{4}-\d{2}-\d{2}$/.test(exCheckout)) {
    const dias = Math.round(
      (Date.parse(exCheckout + 'T00:00:00Z') - Date.parse(exCheckin + 'T00:00:00Z')) / 86400000);
    exCheckout = new Date(Date.parse(corrigido + 'T00:00:00Z') + dias * 86400000)
      .toISOString().slice(0, 10);
  }
  exCheckin = corrigido;
}

const checkin = escolher(exCheckin, sessao.data_checkin);
const checkout = escolher(exCheckout, sessao.data_checkout);
const pessoas = escolher(extraido.qtd_pessoas, sessao.qtd_pessoas);
const nome = escolher(extraido.nome, sessao.nome_cliente) || base.nomeWhats || null;

// ---------- O feriado, quando a pessoa so disse o nome ----------
// Mesma licao do ano: o modelo nao sabe em que dia cai o carnaval. Em
// 18/08/2026 ele traduziu "carnaval 2027" para 18 a 22/02/2027 (o certo e
// 05 a 10/02) e a cliente quase reservou a semana SEGUINTE ao feriado,
// pagando diaria de semana no lugar do pacote. Agora o nome viaja cru ate
// o site, que tem o algoritmo da Pascoa e devolve o bloco fechado.
//
// So vale quando nao ha periodo: data dita pelo cliente sempre manda.
const feriado = extraido.feriado || null;
const anoFeriado = Number(extraido.ano_feriado) || null;

// A DATA VAI PARA O SITE SEMPRE QUE HOUVER ENTRADA E SAIDA.
//
// Antes ela so ia acompanhada do numero de pessoas. Quem perguntava por
// uma data sem dizer quantas pessoas ia recebia do site "o cliente ainda
// nao informou data" — e a IA, sem nenhum fato sobre aquele periodo,
// concluia sozinha que estava ocupado. Foi assim que 02 a 04/10/2026, que
// estava livre, foi negado duas vezes a um cliente em 14/08/2026.
//
// Disponibilidade nao depende de quantas pessoas vao. So o preco depende.
const temPeriodo = Boolean(checkin && checkout);
const temTudo = Boolean(temPeriodo && pessoas);

return [{
  json: {
    telefone: base.telefone,
    texto: base.texto,
    tipo: base.tipo,
    quantidade: base.quantidade || 1,
    nome,
    intencao: extraido.intencao || 'OUTRO',
    pergunta: extraido.pergunta || null,
    hidromassagem: extraido.hidromassagem === true,
    data_checkin: checkin,
    data_checkout: checkout,
    qtd_pessoas: pessoas,
    feriado,
    temTudo,
    historico_resumido: sessao.historico_resumido || '',
    // Sem data o site devolve a tabela de precos; com data, devolve tambem
    // a disponibilidade, mesmo que o preco ainda nao possa ser calculado.
    // Com o nome do feriado e sem data, ele resolve o bloco e responde
    // sobre ele.
    corpoConsulta: {
      checkin: temPeriodo ? checkin : '',
      checkout: temPeriodo ? checkout : '',
      pessoas: pessoas || 0,
      hidromassagem: extraido.hidromassagem === true,
      feriado: feriado || '',
      ano: anoFeriado || 0,
    },
  }
}];

// Extrai o texto da IA, limpa e quebra em BALOES.
//
// Gente nao manda paragrafo de oitenta palavras no WhatsApp. Em
// 18/08/2026 a Julia mandou quatro blocos desses seguidos, cada um com
// disponibilidade + valor + caucao + lista de atrativos + pergunta, e o
// resultado parecia formulario. O prompt agora pede blocos separados por
// linha em branco; aqui eles viram mensagens separadas de verdade.
const dados = $('Montar Resposta').first().json.dados;

let texto = '';
try {
  texto = $input.first().json.choices[0].message.content.trim();
} catch (e) {
  texto = 'Oi! Tive um probleminha técnico aqui. Pode repetir, por favor?';
}

// WhatsApp nao e markdown. O modelo escorrega em asterisco e traco de
// lista mesmo com o prompt proibindo — limpar aqui sai mais barato do que
// torcer para ele obedecer.
function limpar(s) {
  return String(s || '')
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/[*_`#]/g, '')
    // `\s` aqui comeria a linha em branco anterior e grudaria dois
    // balões num só. So espaco e tabulacao.
    .replace(/^[ \t]*[-•][ \t]+/gm, '')
    .replace(/[ \t]+$/gm, '')
    .trim();
}

// Balao curto demais sozinho parece robo travando ("Oi!" numa mensagem so),
// e mais de tres seguidos parecem metralhadora. Os dois limites existem
// para a conversa continuar parecendo conversa.
const MIN_BALAO = 15;
const MAX_BALOES = 3;
const BALAO_CHEIO = 200;

function emBaloes(s) {
  const limpo = limpar(s);
  const partes = limpo
    .split(/\n\s*\n+/)
    .map((p) => p.replace(/\n+/g, ' ').trim())
    .filter(Boolean);

  const juntos = [];
  for (const p of partes) {
    const ultimo = juntos[juntos.length - 1];
    const curto = p.length < MIN_BALAO || (ultimo && ultimo.length < MIN_BALAO);
    // Um balao cheio nao adota mais ninguem: sem esse teto, uma resposta
    // toda picotada acabava colapsada numa mensagem so.
    if (juntos.length && curto && ultimo.length + p.length <= BALAO_CHEIO) {
      juntos[juntos.length - 1] = ultimo + ' ' + p;
    } else {
      juntos.push(p);
    }
  }

  if (juntos.length > MAX_BALOES) {
    return juntos
      .slice(0, MAX_BALOES - 1)
      .concat(juntos.slice(MAX_BALOES - 1).join(' '));
  }

  return juntos.length ? juntos : [limpo];
}

const baloes = emBaloes(texto);

// No historico cada turno ocupa UMA linha: o corte de 32 linhas conta
// linhas, e uma resposta em tres balões comeria tres turnos do cliente.
const anterior = dados.historico_resumido || '';
const novoTurno = 'Cliente: ' + (dados.texto || '[áudio]')
  + '\nJúlia: ' + baloes.join(' ');
const historico = (anterior + '\n' + novoTurno)
  .split('\n')
  .filter(Boolean)
  .slice(-32)
  .join('\n');

return [{
  json: {
    telefone: dados.telefone,
    texto: baloes.join('\n\n'),
    baloes,
    sessao: {
      telefone: dados.telefone,
      nome_cliente: dados.nome,
      data_checkin: dados.data_checkin,
      data_checkout: dados.data_checkout,
      qtd_pessoas: dados.qtd_pessoas,
      historico_resumido: historico,
      updated_at: new Date().toISOString(),
    }
  }
}];

// Um item por balao — o `Enviar WhatsApp` roda uma vez para cada, com
// batchSize 1 para nao trocar a ordem no caminho.
//
// A quebra fica separada do `Preparar Envio` de proposito: aquele no
// continua devolvendo UM item, e e dele que sai o `Salvar Sessao`. Se a
// divisao acontecesse la, a sessao seria gravada uma vez por balao.
const item = $input.first().json;
const baloes = Array.isArray(item.baloes) && item.baloes.length
  ? item.baloes
  : [item.texto];

return baloes
  .map((texto) => String(texto || '').trim())
  .filter(Boolean)
  .map((texto, i) => ({
    json: {
      telefone: item.telefone,
      texto,
      ordem: i + 1,
      total: baloes.length,
    }
  }));
